function AdminEvolutionChartV66({finances,projects}:{finances:Row[],projects:Row[]}){const year=new Date().getFullYear();const months=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];const revenue=Array(12).fill(0),projectSeries=Array(12).fill(0);for(const f of finances){const d=new Date(Number(f.created||f.updated||Date.now()));if(!Number.isNaN(d.getTime())&&d.getFullYear()===year&&String(f.entry_type)==='Receita'&&String(f.status)==='Pago')revenue[d.getMonth()]+=Number(f.amount_cents||0)/100}for(const p of projects){const d=new Date(Number(p.created||Date.now()));if(!Number.isNaN(d.getTime())&&d.getFullYear()===year)projectSeries[d.getMonth()]+=1}const max=Math.max(1,...revenue,...projectSeries.map(v=>v*1000));const pts=(arr:number[],scale=1)=>arr.map((v,i)=>({x:34+i*(610/11),y:155-(v*scale/max)*126}));const rpts=pts(revenue),ppts=pts(projectSeries,1000);const path=(a:{x:number,y:number}[])=>a.map((p,i)=>(i?'L':'M')+p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' ');return <section className="admin-panel-v65 admin-evolution-v66"><div className="admin-section-head-v65"><h3>Evolução de Vendas — {year}</h3><div className="admin-chart-legend-v66"><span><i className="rev"/>Receita</span><span><i className="proj"/>Projetos</span></div></div><svg viewBox="0 0 680 190" role="img" aria-label={`Evolução mensal de receitas e projetos em ${year}`}>{[0,1,2,3,4].map(i=><line key={'h'+i} x1="34" y1={28+i*31} x2="644" y2={28+i*31} className="grid"/>)}{months.map((m,i)=><text key={m} x={34+i*(610/11)} y="181" textAnchor="middle">{m}</text>)}<path d={path(rpts)} className="revenue"/><path d={path(ppts)} className="projects"/>{rpts.map((p,i)=><circle key={'r'+i} cx={p.x} cy={p.y} r="3.5" className="revenue-dot"/>)}{ppts.map((p,i)=><circle key={'p'+i} cx={p.x} cy={p.y} r="3" className="project-dot"/>)}</svg></section>}
function AdminServicesV66({leads}:{leads:Row[]}){const defs=[['Sites Institucionais','site'],['Lojas Virtuais','loja'],['Landing Pages','landing'],['Portais e sistemas','portal'],['Manutenção','manuten'],['Consultoria','consult']];const items=defs.map(([label,key])=>({label,value:leads.filter(l=>String(l.service||'').toLowerCase().includes(key)).length}));const total=items.reduce((a,x)=>a+x.value,0);return <section className="admin-panel-v65 admin-services-v66"><h3>Principais Serviços</h3>{items.map((x,i)=>{const pct=total?Math.round(x.value/total*100):0;return <div key={x.label}><span><b>{x.label}</b><small>{pct}%</small></span><i><em className={'s'+i} style={{width:pct?Math.max(3,pct)+'%':'0%'}}/></i></div>})}{!total&&<p className="muted">Nenhum dado real de serviços disponível ainda.</p>}</section>}
